title = #{title}, description = #{description}, address = #{address}, province = #{province}, city = #{city}, district = #{district}, latitude = #{latitude}, longitude = #{longitude}, price = #{price}, deposit = #{deposit}, area = #{area}, room_count = #{roomCount}, hall_count = #{hallCount}, bathroom_count = #{bathroomCount}, floor = #{floor}, total_floor = #{totalFloor}, orientation = #{orientation}, rent_type = #{rentType}, available_date = #{availableDate}, utilities = #{utilities}, requirements = #{requirements}, status = #{status}, update_time = NOW()
